The following Terraform configuration creates two AWS S3 buckets with distinct names. One bucket is configured as a private source bucket, and the other is configured as a logging target bucket that allows S3 log delivery writes. Server access logging is enabled on the private bucket, sending logs to the logging bucket with a specified prefix.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the S3 buckets will be created."
  type        = string
  default     = "us-east-1"
}

